import { Component, computed, input } from '@angular/core';
import {
  TablerIconComponent,
  IconFileTypePdf, IconFileTypeDoc, IconFileTypeXls, IconFileTypePpt,
  IconFileTypeZip, IconPhoto, IconFile,
} from '@tabler/icons-angular';

/** hrm-file-cell — ô tệp: icon theo loại (đuôi tệp) + tên tệp + kích thước.
 *  Icon + tông màu tự suy từ đuôi (pdf→đỏ, doc→xanh, xls→lục, ảnh→tím…). */
@Component({
  selector: 'hrm-file-cell',
  imports: [TablerIconComponent],
  template: `
    <span class="fc-ic" [attr.data-tone]="meta().tone">
      <tabler-icon [icon]="meta().icon" [size]="18" />
    </span>
    <span class="fc-body">
      <span class="fc-name">{{ name() }}</span>
      @if (size()) { <span class="fc-size">{{ size() }}</span> }
    </span>
  `,
  host: { class: 'hrm-file-cell' },
  styles: [`
:host { display: inline-flex; align-items: center; gap: 10px; min-width: 0; max-width: 100%; }
.fc-ic { flex: none; width: 32px; height: 32px; border-radius: var(--radius-md); display: grid; place-items: center; }
.fc-ic[data-tone='red']    { background: var(--error-bg);   color: var(--error-base); }
.fc-ic[data-tone='blue']   { background: var(--info-bg);    color: var(--info-base); }
.fc-ic[data-tone='green']  { background: var(--success-bg); color: var(--success-base); }
.fc-ic[data-tone='amber']  { background: var(--warning-bg); color: var(--warning-base); }
.fc-ic[data-tone='purple'] { background: var(--feature-bg); color: var(--feature-base); }
.fc-ic[data-tone='neutral']{ background: var(--bg-surface-subtle); color: var(--text-sub); }
.fc-body { display: flex; flex-direction: column; min-width: 0; }
.fc-name { font-size: var(--fs-14); color: var(--text-strong); line-height: 1.35;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.fc-size { font-size: var(--fs-12); color: var(--text-sub); line-height: 1.3; }
  `],
})
export class HrmFileCell {
  readonly name = input('');
  /** Kích thước đã định dạng (VD "2,4 MB"). Bên gọi cấp để tránh phụ thuộc locale. */
  readonly size = input('');
  /** Ép loại tệp (đuôi) nếu tên không có đuôi; VD 'pdf'. */
  readonly ext = input('');

  protected readonly meta = computed(() => {
    const raw = (this.ext() || this.name().split('.').pop() || '').toLowerCase();
    switch (raw) {
      case 'pdf': return { icon: IconFileTypePdf, tone: 'red' };
      case 'doc': case 'docx': return { icon: IconFileTypeDoc, tone: 'blue' };
      case 'xls': case 'xlsx': case 'csv': return { icon: IconFileTypeXls, tone: 'green' };
      case 'ppt': case 'pptx': return { icon: IconFileTypePpt, tone: 'amber' };
      case 'zip': case 'rar': case '7z': case 'gz': return { icon: IconFileTypeZip, tone: 'amber' };
      case 'jpg': case 'jpeg': case 'png': case 'gif': case 'svg': case 'webp':
        return { icon: IconPhoto, tone: 'purple' };
      default: return { icon: IconFile, tone: 'neutral' };
    }
  });
}
